_VIDHYORA_SLUGS = ['vidhyora-ai-1-month', 'vidhyora-ai-6-months', 'vidhyora-ai-1-year']


def unseed_ai_models(apps, schema_editor):
    Product = apps.get_model('myapp', 'Product')
    for product in Product.objects.filter(slug__in=_VIDHYORA_SLUGS):
        if '{{AI_MODELS}}' in product.description:
            product.description = product.description.replace('{{AI_MODELS}}', _OLD_DESC_BLOCK)
        if 'Models: {{AI_MODELS}}' in product.specs:
            product.specs = product.specs.replace('Models: {{AI_MODELS}}', _OLD_SPECS_LINE)
        if '{{AI_MODELS}}' in product.tags:
            product.tags = product.tags.replace('{{AI_MODELS}}', _OLD_TAGS_BLOCK)
        product.save(update_fields=['description', 'specs', 'tags'])


